import {node,downloadFile} from './experience.js';
import {getSavedGift,putSavedGift} from './gift-library.js';
export function cleanReplies(value){return Array.isArray(value)?value.filter(item=>item&&typeof item.message==='string'&&item.message.trim()).slice(-100).map(item=>({id:String(item.id||'').slice(0,100),message:item.message.slice(0,2000),createdAt:String(item.createdAt||'').slice(0,40)})):[];}
export function applyResponse(state,value){
 if(!value||value.giftId!==state.draftId)throw Error('Esta resposta pertence a outro presente.');
 if(value.type==='capimimo-rsvp'){
  if(!['accepted','declined'].includes(value.status)||!Number.isInteger(value.count)||value.count<0)throw Error('Confirmação inválida.');const guests=(state.guests||[]).map(guest=>({...guest})),normalize=name=>String(name||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase(),matches=guests.filter(guest=>value.guestId?guest.id===value.guestId:normalize(guest.name)===normalize(value.name));if(matches.length!==1)throw Error('Não encontrei esse convidado na lista deste convite.');const guest=matches[0];if(value.count>guest.allowedCount||value.status==='accepted'&&value.count<1||value.status==='declined'&&value.count!==0)throw Error('A quantidade de pessoas não corresponde a este convite.');guest.status=value.status;guest.attendingCount=value.count;return {...state,guests};
 }
 if(typeof value.message!=='string'||!value.message.trim()||value.message.length>2000||typeof value.id!=='string'||!value.id||value.id.length>100)throw Error('Arquivo de resposta inválido.');const replies=cleanReplies(state.replies);if(replies.some(reply=>reply.id===value.id))throw Error('Esta resposta já foi importada.');if(replies.length>=100)throw Error('Este presente já tem 100 respostas guardadas.');return {...state,replies:[...replies,{id:value.id,message:value.message.trim(),createdAt:String(value.createdAt||'').slice(0,40)}]};
}
export function initReplyInbox({getState,onChange,toast}){
 const panel=node('details','reply-inbox options-panel');panel.innerHTML='<summary>Respostas que chegaram</summary><p>Importe os arquivos devolvidos por quem recebeu o presente. Respostas escritas ficam aqui; confirmações atualizam a lista de convidados. Nada é enviado automaticamente.</p><label class="response-upload-label">Importar respostas ou confirmações<input type="file" accept="application/json,.json" multiple></label><div class="reply-inbox-list"></div><button type="button" class="export-replies">Baixar respostas guardadas</button><p class="reply-import-status" role="status"></p>';document.querySelector('.customizer-bottom').before(panel);let rendered='',importQueue=Promise.resolve();
 function importFiles(files){const batch=[...files],task=importQueue.then(()=>importBatch(batch));importQueue=task.catch(()=>{});return task;}
 const responsePatch=(state,value)=>{const next=applyResponse(state,value);return value.type==='capimimo-rsvp'?{guests:next.guests}:{replies:next.replies};};
 const alreadyImported=(state,value)=>value.type!=='capimimo-rsvp'&&cleanReplies(state.replies).some(reply=>reply.id===value.id);
 async function importBatch(files){let imported=0;const errors=[];for(const file of files){try{if(file.size>25000)throw Error('Use um arquivo JSON de até 25 KB.');const value=JSON.parse(await file.text()),saved=await getSavedGift(value.giftId).catch(error=>{if(value.giftId===getState().draftId)return null;throw error;});const active=getState(),editing=value.giftId===active.draftId;if(!editing&&!saved)throw Error('O presente desta resposta não está na sua biblioteca.');const patch=responsePatch(editing?active:saved.state,value);if(editing)onChange(patch);if(saved){let savedPatch;if(editing&&value.type==='capimimo-rsvp'){const normalize=name=>String(name||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase(),updated=patch.guests.find(guest=>value.guestId?guest.id===value.guestId:normalize(guest.name)===normalize(value.name)),guests=(saved.state.guests||[]).map(guest=>({...guest})),at=guests.findIndex(guest=>guest.id===updated.id);if(at<0)guests.push({...updated});else guests[at]={...guests[at],...updated};savedPatch={guests};}else savedPatch=alreadyImported(saved.state,value)?{}:responsePatch(saved.state,value);saved.state={...saved.state,...savedPatch};await putSavedGift(saved);}const latest=getState();if(latest.draftId===value.giftId&&(!editing||latest!==active)&&!alreadyImported(latest,value))onChange(responsePatch(latest,value));imported++;}catch(error){errors.push(error instanceof SyntaxError?'Arquivo JSON inválido.':error.message);}}

  const message=(imported?imported+(imported===1?' resposta importada. ':' respostas importadas. '):'')+errors.join(' ');panel.querySelector('.reply-import-status').textContent=message;toast(message);render();return imported;
 }
 panel.querySelector('input').addEventListener('change',async event=>{await importFiles([...event.target.files]);event.target.value='';});panel.querySelector('.export-replies').addEventListener('click',()=>downloadFile('capimimo-respostas-guardadas.json',new Blob([JSON.stringify({giftId:getState().draftId,replies:cleanReplies(getState().replies)},null,2)],{type:'application/json'})));
 function render(){const replies=cleanReplies(getState().replies),signature=JSON.stringify(replies);panel.querySelector('.export-replies').hidden=!replies.length;if(signature===rendered)return;rendered=signature;const list=panel.querySelector('.reply-inbox-list');list.replaceChildren();for(const reply of replies){const article=node('article','reply-inbox-note'),message=node('p','',reply.message),when=node('small');const date=new Date(reply.createdAt);when.textContent=Number.isNaN(date.getTime())?'Resposta recebida':date.toLocaleString('pt-BR');const remove=node('button','','Excluir resposta');remove.type='button';remove.addEventListener('click',()=>{if(confirm('Excluir esta resposta guardada neste aparelho?'))onChange({replies:cleanReplies(getState().replies).filter(item=>item.id!==reply.id)});});article.append(message,when,remove);list.append(article);}}
 render();return {render,importFiles};
}
